package io.github.romainmichaux.fieldinvestigations.client;

import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvent;

// The mod's own sound effects (assets/cobblemon_field_investigations/sounds, generated by outils/gen_sons.py).
// UI sounds played client-side only, so they do not need to be registered on the server.
final class Sounds {
    static final SoundEvent SIEVE = event("sieve"), PLASTER = event("plaster"), OVERFLOW = event("overflow"), TWEEZERS = event("tweezers"),
            PLUCK = event("pluck"), SHUTTER = event("shutter"), RUB = event("rub"), BRUSH_SOUND = event("brush"),
            VIAL = event("vial"), BUBBLE = event("bubble"), HEARTBEAT = event("heartbeat"), ROPE = event("rope"), CARABINER = event("carabiner"),
            BRANCH = event("branch"), CRACK = event("crack"), KNOCK = event("knock"), ROCKSLIDE = event("rockslide"),
            PICKAXE = event("pickaxe"), STONE = event("stone"), DROP = event("drop"), KNOB = event("knob"), ICE = event("ice"),
            FLAME = event("flame"), WHISTLE = event("whistle"), LAMP = event("lamp"), TICK = event("tick"), CLICK = event("click"),
            PAPER = event("paper"), SCAN = event("scan"), CHIME = event("chime"), SUCCESS = event("success"), FAILURE = event("failure"),
            IDENTIFIED = event("identified"), RANK_UP = event("rank_up");
    private Sounds() {}

    private static SoundEvent event(String name) {
        return SoundEvent.createVariableRangeEvent(ResourceLocation.fromNamespaceAndPath("cobblemon_field_investigations", name));
    }
}
